function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const budget = multisetDiff(before.budget, after.budget);
  const spend = multisetDiff(before.spend, after.spend);
  return {
    rels: [
      { rel: "budget", add: budget.add, del: budget.del },
      { rel: "spend", add: spend.add, del: spend.del },
    ],
    carryPending: false,
  };
}

